const settings = $input.first().json;
const input = $('When Executed by GPT Workflow').first().json;
const maxAttempts = Math.max(1, Math.min(100, Number(settings.max_proxy_attempts || 10)));
const lineAttemptLimit = Math.ceil(maxAttempts / 2);
const items = [];
for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const preferLineProxy = attempt <= lineAttemptLimit;
  const gatewayAttempt = preferLineProxy ? attempt : attempt - lineAttemptLimit;
  const request = JSON.parse(JSON.stringify(settings.lease_request || {}));
  request.policy = request.policy || {};
  request.policy.labels = {
    ...(request.policy.labels || {}),
    attempt: String(gatewayAttempt),
    workflow_attempt: String(attempt),
    max_proxy_attempts: String(maxAttempts),
  };
  request.chain_policy = {
    ...(request.chain_policy || {}),
    country_code: settings.country_code || request?.policy?.labels?.country_code || request?.policy?.region || '',
    region: settings.region || request?.policy?.labels?.region || request?.policy?.region || '',
    purpose: settings.purpose || request.purpose || 'REGISTER_PROTOCOL',
    max_attempts: maxAttempts,
    allow_direct_dynamic_gateway: true,
    prefer_line_proxy: preferLineProxy,
  };
  items.push({ json: {
    ...input,
    settings,
    attempt,
    gateway_attempt: gatewayAttempt,
    prefer_line_proxy: preferLineProxy,
    max_proxy_attempts: maxAttempts,
    preflight_enabled: !!settings.preflight_enabled,
    cf_canary_enabled: !!settings.cf_canary_enabled,
    require_residential: !!settings.require_residential,
    min_ip_purity_score: Number(settings.min_ip_purity_score || 0),
    lease_request: request,
  }});
}
return items;

const attempt = $('Loop Proxy Attempts').first().json;
const leaseResponse = $input.first().json;
function endpoint(leaseResponse) {
  const session = leaseResponse?.lease?.session || {};
  return leaseResponse?.egress || leaseResponse?.lease?.egress || session.egress || {};
}
function endpointUrl(egress) {
  if (!egress?.host || !egress?.port) return '';
  const protocol = egress.protocol === 'PROXY_PROTOCOL_SOCKS5' ? 'socks5' : 'http';
  return `${protocol}://${egress.host}:${egress.port}`;
}
const session = leaseResponse?.lease?.session || {};
const egress = endpoint(leaseResponse);
return [{ json: {
  ...attempt,
  lease_response: leaseResponse,
  proxy_url: endpointUrl(egress),
  check_request: {
    pool_id: 'default',
    provider_id: session.provider_id || egress.provider_id || '',
    listener_id: egress.id || '',
  },
}}];

const base = $('Build Proxy Check Request').first().json;
