const geo = body?.proxy_exit_geo || {};
const ok = httpOK(response) && !!geo.ip;
const errorMessage = ok ? '' : (body?.message || body?.error || response.statusMessage || 'proxy exit geo failed');
const data = build(base, { proxy_exit_geo: geo }, {}, {}, false, errorMessage);
return [{ json: { ...base, geo_response: { proxy_exit_geo: geo }, success: ok, error_message: errorMessage, data: data.data } }];
function httpBody(response) { return response && Object.prototype.hasOwnProperty.call(response, 'body') ? response.body : response; }
function httpOK(response) { return !response?.statusCode || (response.statusCode >= 200 && response.statusCode < 300); }

function build(base, geoResponse, fraudResponse, edgeResponse, accepted, errorMessage) {
  const lease = base.lease_response?.lease || {};
  const session = lease.session || {};
  const egress = base.lease_response?.egress || lease.egress || session.egress || {};
  const exit = geoResponse?.proxy_exit_geo || {};
  const fraud = fraudResponse?.check || {};
  const edge = edgeResponse?.check || {};
  const riskScore = Number(fraud.risk_score || 0);
  return {
    job_id: base.job_id,
    account_id: base.account_id,
    n8n_execution_id: base.n8n_execution_id,
    success: accepted,
    proxy_url: base.proxy_url,
    error_message: errorMessage || '',
    data: {
      purpose: base.settings?.purpose || base.lease_request?.purpose || 'REGISTER_PROTOCOL',
      attempt: base.attempt,
      max_proxy_attempts: base.max_proxy_attempts,
      accepted,
      error_message: errorMessage || '',
      preflight_enabled: !!base.preflight_enabled,
      cf_canary_enabled: !!base.cf_canary_enabled,
      proxy_session_hash: stableHash(session.session_id),
      proxy_protocol: egress.protocol || '',
