      fraud_risk_level: fraud.risk_level || '',
      fraud_risk_score: riskScore,
      ip_purity_score: fraud.risk_level ? Math.max(0, Math.min(100, 100 - riskScore)) : 0,
      fraud_risk_signals: fraud.risk_signals || [],
      edge_risk_level: edge.risk_level || '',
      edge_risk_score: Number(edge.risk_score || 0),
      edge_risk_signals: edge.risk_signals || [],
      proxy_runtime_lease: {
        lease_id: lease.lease_id || '',
        provider_account_id: lease.provider_account_id || '',
        provider_id: session.provider_id || '',
        expires_at: lease.expires_at || session.expires_at || '',
      },
      chain_plan: base.lease_response?.chain_plan || lease.chain_plan || {},
      chain: chainSummary(base.lease_response?.chain_plan || lease.chain_plan || {}),
    },
  };
}
function stableHash(value) {
  let hash = 2166136261;
  for (const ch of String(value || '')) { hash ^= ch.charCodeAt(0); hash = Math.imul(hash, 16777619); }
  return (hash >>> 0).toString(16).padStart(8, '0');
}
function chainSummary(plan) {
  return {
    chain_id: plan.chain_id || '',
    line_source_id: plan.line?.source_id || '',
    line_node_id: plan.line?.node_id || '',
    line_display_name: plan.line?.display_name || '',
    dynamic_provider_account_id: plan.dynamic_gateway?.provider_account_id || '',
    dynamic_provider_id: plan.dynamic_gateway?.provider_id || '',
    dynamic_gateway_id: plan.dynamic_gateway?.gateway_id || '',
    dynamic_gateway_name: plan.dynamic_gateway?.display_name || '',
  };
}

